INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261113-colom-mississippi-senate', 'scott-colom-wins-mississippi-senate-race-hyde-smith-concedes', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Scott Colom wins Mississippi''s Senate race, flipping a Republican seat as Hyde-Smith concedes', 'The Associated Press called the race on Wednesday, Nov. 11, more than a week after the election. Colom becomes the first Black U.S. senator elected from Mississippi since Reconstruction.', 'Democrat Scott Colom defeated Republican Sen. Cindy Hyde-Smith in Mississippi, the Associated Press projected on Wednesday, Nov. 11, ABC News reported. With 99% of the expected vote counted, Colom had 49.2% to Hyde-Smith''s 48.7%, a lead of about 4,700 votes. The race took more than a week to call after the Nov. 3 election.

## A historic result

Colom is the first Black U.S. senator elected from Mississippi since Reconstruction in the 1870s, according to ABC News, and the win is the eighth Senate seat Democrats have picked up this cycle. At a victory rally in Jackson, Colom invoked Hiram Rhodes Revels and Medgar Evers.

Colom is a district attorney for four counties along the Mississippi-Alabama line. He was once nominated to be a federal district judge, a nomination Hyde-Smith blocked in 2023, ABC News reported.

## Concession and congratulations

Hyde-Smith called Colom to concede on the evening of Wednesday, Nov. 11. In a video, she said she respected the decision of Mississippi voters, ABC News reported. Republican Gov. Tate Reeves congratulated "Senator-Elect Scott Colom" in a statement and said he hoped to work with him on behalf of Mississippi families, WLOX reported.

## What comes next

Both campaigns had prepared for possible court fights over affidavit ballots before the call. Counties must certify their results by Friday, Nov. 13, according to WLOX.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:46900:46991/full/pct:25/0/default.jpg', 'The Mississippi State Capitol in Jackson (file). Photo: Carol M. Highsmith / Library of Congress (highsm.46991), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-13.sql', 9, 1, 'newsroom-assistant', '2026-11-13T10:45:00.000Z', '2026-11-13T10:45:00.000Z');
