INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261113-van-hollen-schumer', 'van-hollen-challenges-schumer-senate-democratic-leader', 'newsroom', 'news_story', 'congress', 'EDITORIAL_REVIEW', 0, 'Van Hollen launches a challenge to Schumer for Senate Democratic leader', 'The Maryland senator announced his bid on Thursday, Nov. 12. Schumer says he has the votes, and the closed-door election is set for Tuesday, Dec. 1.', 'Sen. Chris Van Hollen of Maryland said on Thursday, Nov. 12, that he will run for Senate Democratic leader in the next Congress, challenging Sen. Chuck Schumer of New York, the Associated Press reported. Democrats won the Senate majority in the Nov. 3 midterms, so the winner is expected to become majority leader.

## The case for change

Van Hollen said the American people "called for change" and that Democrats need new leadership to meet the moment, according to the AP. He told *Time* he has "more than 10" of the 55 Democratic senators and senators-elect behind him and acknowledged he is the underdog. *Time* reported that the last contested race for the post was in 1994.

## Schumer''s response

Schumer said he welcomed a discussion about the caucus''s future and that he has "the votes to continue serving as Democratic Leader," the AP reported. *Time* counted 14 senators and senators-elect publicly backing Schumer, including Sens. Kirsten Gillibrand, Tim Kaine and John Fetterman. Incoming Ohio Sen. Sherrod Brown, Sen. Angus King of Maine and Sen. Catherine Cortez Masto of Nevada also back him, according to the AP.

## Who backs Van Hollen

Sen. Bernie Sanders and Michigan Sen.-elect Abdul El-Sayed have endorsed Van Hollen. Sen. Elissa Slotkin of Michigan has said she will not support Schumer but has not endorsed Van Hollen, *Time* reported. Senate Democrats will vote by secret ballot on Tuesday, Dec. 1, and the new Congress convenes on Monday, Jan. 4.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:16600:16698/full/pct:25/0/default.jpg', 'The Maryland State House in Annapolis (file). Photo: Carol M. Highsmith / Library of Congress (highsm.16698), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-13.sql', 8, 0, 'newsroom-assistant', '2026-11-13T10:45:00.000Z', '2026-11-13T10:45:00.000Z');
