INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261113-alaska-senate-count', 'alaska-senate-race-uncalled-judge-denies-peltola-ballot-data-request', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Alaska''s Senate race remains the last one uncalled as a judge rejects Peltola''s request for ballot data', 'Peltola still leads Sen. Dan Sullivan, but neither has a majority. Ranked-choice tabulation is set for Wednesday, Nov. 18.', 'Alaska''s U.S. Senate race is the only one in the country that has not been called, PBS NewsHour reported. Democrat Mary Peltola led Republican Sen. Dan Sullivan 48.9% to 47.3% as of Wednesday, Nov. 11, with about 89% of ballots counted, according to *USA Today*.

## The court ruling

Superior Court Judge Thomas Matthews on Wednesday, Nov. 11, denied a request from Peltola''s campaign for a list of voters whose absentee ballots were rejected and the reasons for each rejection, PBS NewsHour reported. The campaign said it wanted to make sure all qualified voters have their ballots counted. The state argued that the request raised voter privacy concerns and would pull staff away from counting. The judge called the request "not reasonable" given the time pressure on election officials and said the records could not be produced or redacted at this stage.

## What comes next

Because no candidate has more than 50% of first-choice votes, the race is expected to be decided by ranked-choice tabulation. The Division of Elections plans to run it on Wednesday, Nov. 18, which is also the last day overseas absentee ballots can arrive, according to PBS NewsHour and *USA Today*. Democrats have already won control of the Senate.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:04300:04371/full/pct:25/0/default.jpg', 'Downtown Main Street view of Anchorage, Alaska (file). Photo: Carol M. Highsmith / Library of Congress (highsm.04371), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-13.sql', 7, 0, 'newsroom-assistant', '2026-11-13T10:45:00.000Z', '2026-11-13T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261113-alaska-senate-count-src1', 'bd-20261113-alaska-senate-count', 'Alaska judge rules a request by Peltola campaign for ballot data in Senate race is ''not reasonable''', 'https://www.pbs.org/newshour/politics/alaska-judge-rules-a-request-by-peltola-campaign-for-ballot-data-in-senate-race-is-not-reasonable', 'PBS NewsHour (AP)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-13T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-13. Editor to confirm.', 'newsroom-assistant', '2026-11-13T10:45:00.000Z');
