INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261113-ibogaine-research', 'hhs-funds-ibogaine-ptsd-research-kennedy-collins', 'newsroom', 'news_story', 'policy', 'EDITORIAL_REVIEW', 0, 'Kennedy and Collins announce federal money to prepare the first U.S. studies of ibogaine for PTSD', 'HHS committed up to $4.9 million on Thursday, Nov. 12, for groundwork on the psychedelic drug, which is illegal in the United States, and opened a $20 million program for fast-acting mental health drugs.', 'Health Secretary Robert F. Kennedy Jr., joined by Veterans Affairs Secretary Doug Collins, announced on Thursday, Nov. 12, that the federal government will fund early work toward the first U.S. studies of ibogaine as a treatment for post-traumatic stress disorder, the Associated Press reported.

## What the money pays for

The Advanced Research Projects Agency for Health (ARPA-H) committed up to $4.9 million over five years, according to an HHS announcement. The first awards go to Mark Cuban Cost Plus Drug Company, to lay groundwork for a domestically made ibogaine product, and to Beond Inc., to generate data on safety and dosing. The money does not pay for treating patients or for clinical trials, HHS said. Beond has treated more than 3,000 patients with ibogaine at a clinic in Mexico, the AP reported.

HHS also said the National Institute of Mental Health will fund a $20 million research network to study fast-acting psychiatric drugs such as ketamine, esketamine and psilocybin, with recipients to be named in the summer of 2027.

## Risks and reaction

Ibogaine comes from a West African shrub. It can cause intense hallucinations, nausea and vomiting, and sometimes deadly irregular heart rhythms, and it is in the same restrictive federal drug class as LSD, the AP reported. Collins said the effort would put safety first and that veterans with PTSD are owed "both urgency and the best science." Kennedy predicted a "record" approval process. President Trump signed an executive order in April 2026 to speed up psychedelic research.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:25100:25148/full/pct:25/0/default.jpg', 'The Hubert H. Humphrey Building, HHS headquarters, Washington, D.C. (file). Photo: Carol M. Highsmith / Library of Congress (highsm.25148), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-13.sql', 7, 0, 'newsroom-assistant', '2026-11-13T10:45:00.000Z', '2026-11-13T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261113-ibogaine-research-src1', 'bd-20261113-ibogaine-research', 'Trump administration will fund new research on controversial psychedelic drug ibogaine', 'https://laist.com/news/politics/trump-administration-will-fund-new-research-on-controversial-psychedelic-drug-ibogaine', 'LAist (AP)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-13T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-13. Editor to confirm.', 'newsroom-assistant', '2026-11-13T10:45:00.000Z');
