INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261113-bruins-canadiens', 'canadiens-5-bruins-2-homecoming-swayman-pulled', 'newsroom', 'news_story', 'nhl', 'EDITORIAL_REVIEW', 0, 'Canadiens 5, Bruins 2: Montreal scores five straight and ends Boston''s four-game win streak', 'Jeremy Swayman was pulled in the second period at TD Garden on Thursday, Nov. 12. Casey Mittelstadt scored both Boston goals.', 'The Montreal Canadiens beat the Bruins 5-2 at TD Garden on Thursday, Nov. 12, scoring the game''s first five goals and ending Boston''s four-game winning streak, NHL.com reported. It was the Bruins'' Homecoming night, when they debuted college-style Varsity Sweaters, and their first home loss since Oct. 5, according to *The Boston Globe* and Boston Hockey Now.

## How it went

Kirby Dach scored on a wraparound 2:34 into the game, and Josh Anderson made it 2-0 later in the first period. Jake Evans and Cole Caufield scored on breakaways early in the second, and coach Marco Sturm pulled Jeremy Swayman after Caufield''s goal. Swayman allowed four goals on 17 shots, and Michael DiPietro made 13 saves in relief, NHL.com reported. Phillip Danault made it 5-0 before Casey Mittelstadt scored late in the second and again 52 seconds into the third. Elias Lindholm assisted on both.

Montreal rookie Jacob Fowler, a former Boston College goalie, made 30 saves. Canadiens forward Chris Kreider left in the third period after a collision and did not return.

## Standings

Boston fell to 13-5-1, while Montreal (12-3-4) extended its point streak to 12 games. Sturm called the Bruins "very flat," and David Pastrnak called the slow start "unacceptable," NHL.com reported. The *Globe* reported that Boston dropped out of first place in the Atlantic Division. The Bruins host the Minnesota Wild on Saturday, Nov. 14.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:14100:14182/full/pct:25/0/default.jpg', 'The Leonard P. Zakim Bunker Hill Memorial Bridge, near TD Garden, Boston (file). Photo: Carol M. Highsmith / Library of Congress (highsm.14182), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-13.sql', 6, 0, 'newsroom-assistant', '2026-11-13T10:45:00.000Z', '2026-11-13T10:45:00.000Z');
