INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261113-patriots-munich-practice', 'patriots-munich-practice-aj-brown-stevenson-lions', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'A.J. Brown practices again as the Patriots open their week in Munich before facing the Lions', 'New England (5-4) arrived in Germany on Thursday, Nov. 12, for its game against Detroit (6-2) at Allianz Arena on Sunday, Nov. 15.', 'The Patriots arrived in Munich on the morning of Thursday, Nov. 12, and held their first practice there ahead of their game against the Detroit Lions at Allianz Arena on Sunday, Nov. 15, *The Boston Globe* reported.

## Injury notes

Wide receiver A.J. Brown, who has an ankle and knee injury and missed the past two games, took part in practice for a second straight day, the team reported, a sign he could return against Detroit. Running back Rhamondre Stevenson, who left the loss to Green Bay with a knee injury, made the trip and worked off to the side. Tight end Cameron Latu and guard Walter Rouse, who is in the concussion protocol, practiced after sitting out Wednesday, Nov. 11.

Center Ben Brown (knee) was ruled out before the trip, and cornerback Carlton Davis III and running back TreVeyon Henderson stayed home, according to the team. Guard Greg Van Roten could come off injured reserve to help a line still missing its starting guards.

## The stakes

New England is 5-4 after the 45-27 home loss to the Packers on Sunday, Nov. 8, in which Drake Maye threw three interceptions. Detroit is 6-2 and averages 27.8 points a game, the *Globe* reported. Offensive coordinator Josh McDaniels said the team has to stop turning the ball over. The Patriots practice again on Friday, Nov. 13, at FC Bayern''s facility and have their bye after the game.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:ggbain:14900:14947/full/pct:50/0/default.jpg', 'Army-Navy football, 1913 (file). Photo: Bain News Service / Library of Congress (ggbain.14947), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-13.sql', 5, 0, 'newsroom-assistant', '2026-11-13T10:45:00.000Z', '2026-11-13T10:45:00.000Z');
