INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261113-commanders-giants', 'commanders-24-giants-21-daniels-diggs-thursday-night-football', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Commanders 24, Giants 21: Daniels finds Diggs for the winning touchdown with 57 seconds left', 'Washington won on the road on Thursday Night Football, Nov. 12, and sealed it with an interception of J.J. McCarthy.', 'Jayden Daniels threw a 32-yard touchdown pass to Stefon Diggs with 57 seconds left, and the Washington Commanders beat the New York Giants 24-21 on Thursday Night Football on Thursday, Nov. 12, Fox Sports reported.

## How it ended

Washington''s defense closed it out when Rasul Douglas intercepted Giants quarterback J.J. McCarthy on New York''s final drive, *USA Today* reported. A short Giants punt gave the Commanders good field position for the go-ahead drive, and Diggs had a 30-yard catch earlier in the game.

Daniels threw two interceptions but was otherwise efficient and ran well, according to *USA Today*. He also threw a 1-yard touchdown to tight end Ben Sinnott, Fox Sports reported. For the Giants, Cam Skattebo ran for two touchdowns and McCarthy hit tight end Isaiah Likely for a 66-yard score. Rookie kicker Dominic Zvada missed a 33-yard field goal.

## The division race

The win leaves Washington two games behind the NFC East-leading Giants, and the Commanders hold the head-to-head tiebreaker, *USA Today* reported.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:ggbain:25400:25487/full/pct:50/0/default.jpg', 'The Polo Grounds, onetime home of the New York Giants, Oct. 10, 1917 (file). Photo: Bain News Service / Library of Congress (ggbain.25487), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-13.sql', 4, 0, 'newsroom-assistant', '2026-11-13T10:45:00.000Z', '2026-11-13T10:45:00.000Z');
