INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261113-76ers-raptors', '76ers-123-raptors-112-maxey-embiid', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, '76ers 123, Raptors 112: Maxey scores 27 as Philadelphia rallies to 10-3', 'Philadelphia came back from a 16-point first-half deficit at home on Thursday, Nov. 12.', 'Tyrese Maxey scored 27 points and the Philadelphia 76ers beat the Toronto Raptors 123-112 at Xfinity Mobile Arena on Thursday, Nov. 12, ESPN reported. Joel Embiid added 20 points and Jaylen Brown had 18.

Toronto led by as many as 16 points in the first half before Philadelphia took control in the third quarter and led 96-87 going into the fourth, according to ESPN. RJ Barrett led all scorers with 31 points for the Raptors, and Immanuel Quickley scored 25. Toronto played without LeBron James, who has a back injury, and without Kawhi Leonard and Scottie Barnes.

The 76ers improved to 10-3, and the Raptors fell to 5-7, according to NBA.com. The Celtics, who beat Toronto 98-93 on Wednesday, Nov. 11, did not play on Thursday.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:56500:56507/full/pct:25/0/default.jpg', 'Comcast Center and the Philadelphia skyline (file). Photo: Carol M. Highsmith / Library of Congress (highsm.56507), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-13.sql', 3, 0, 'newsroom-assistant', '2026-11-13T10:45:00.000Z', '2026-11-13T10:45:00.000Z');
